//! win32k-rust: Rust translation of ReactOS win32k.sys (GDI + USER).
//!
//! Auto-generated by rustconv (per-file). Do not edit translated modules
//! by hand — re-translate via the pipeline. This umbrella `lib.rs` is the
//! one hand-maintained file: each landed `src/{name}.rs` gets a
//! `pub mod {name};` line here (flat layout, like hal-rust/src/x86).
//!
//! Links into `win32k.sys` via a staticlib umbrella + cohabitation
//! (the translated C file is commented out in `win32ss/CMakeLists.txt`
//! and the Rust `#[no_mangle]` symbol takes over, exactly like the
//! ntoskrnl-rust / hal-rust cohabitation pattern).
//!
//! FFI surfaces:
//!   * `win32k_sys::win32k::*` — the win32k-internal API/layouts
//!     (`_WND`, `_DESKTOP`, `Int*`/`Gre*`/`co_*`/`User*`).
//!   * `ntkrnl_sys::ddk::*`   — the ntoskrnl APIs win32k also calls
//!     (`Ex/Ke/Mm/Ob/Ps/Rtl/Zw/Nt*`).

#![no_std]
#![allow(non_snake_case)]
#![allow(non_camel_case_types)]
#![allow(non_upper_case_globals)]
#![allow(unused_unsafe)]
#![allow(dead_code)]
#![allow(unused_variables)]
#![allow(unused_assignments)]
#![allow(unused_mut)]

extern crate ntkrnl_sys;
extern crate ntprintf;
extern crate ntprintf_w;
extern crate win32k_sys;

